1	//! Tool definitions and the loader that walks `~/.config/fornax/tools/`.
2	//!
3	//! A tool is described by a TOML file with at minimum `name`, `description`,
4	//! `parameters` (JSON Schema, passed through to the API verbatim), and
5	//! `handler`. The handler is either `"builtin:<name>"` to invoke hardcoded
6	//! Rust (the 5 default tools ship this way) or `{ shell = [...argv] }` for
7	//! user-defined wrappers around shell commands.
8	
9	use serde::Deserialize;
10	use std::path::{Path, PathBuf};
11	
12	#[derive(Debug, Clone, Deserialize)]
13	pub struct ToolDef {
14	    pub name: String,
15	    pub description: String,
16	    /// JSON Schema for the function's parameters. Stored as a free-form
17	    /// `serde_json::Value` because we don't validate it ourselves — the
18	    /// LLM provider does. Passes through to the API's `tools[].function.
19	    /// parameters` field unchanged.
20	    pub parameters: serde_json::Value,
21	    pub handler: Handler,
22	    #[serde(default)]
23	    pub safety: Safety,
24	}
25	
26	/// Two handler shapes:
27	/// - `handler = "builtin:read_file"` → `Handler::Builtin("read_file")`
28	///   (the prefix is stripped on parse). Dispatched to native Rust.
29	/// - `handler = { shell = ["git", "log", "-n", "{{count}}"] }` →
30	///   `Handler::Shell(...)`. Forked + execed at run time with `{{var}}`
31	///   placeholders substituted from the call's arguments.
32	#[derive(Debug, Clone, Deserialize)]
33	#[serde(untagged)]
34	pub enum Handler {
35	    Builtin(BuiltinRef),
36	    Shell { shell: Vec<String> },
37	}
38	
39	#[derive(Debug, Clone)]
40	pub struct BuiltinRef(pub String);
41	
42	impl<'de> Deserialize<'de> for BuiltinRef {
43	    fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
44	        let s = String::deserialize(d)?;
45	        match s.strip_prefix("builtin:") {
46	            Some(name) if !name.is_empty() => Ok(BuiltinRef(name.to_string())),
47	            _ => Err(serde::de::Error::custom(format!(
48	                "expected handler = \"builtin:<name>\", got '{s}'"
49	            ))),
50	        }
51	    }
52	}
53	
54	#[derive(Debug, Clone, Copy, Default, Deserialize, PartialEq, Eq)]
55	#[serde(rename_all = "lowercase")]
56	pub enum Safety {
57	    /// Execute without prompting. The default — fits read-only tools.
58	    #[default]
59	    Auto,
60	    /// Show an approval card before each invocation. Use for write_file,
61	    /// run_shell, and any user-defined tool that mutates state.
62	    Confirm,
63	}
64	
65	/// User config dir for tool TOMLs. `dirs::config_dir()` per platform plus
66	/// the `fornax/tools/` subpath.
67	pub fn user_tools_dir() -> PathBuf {
68	    dirs::config_dir()
69	        .unwrap_or_else(|| PathBuf::from("."))
70	        .join("fornax")
71	        .join("tools")
72	}
73	
74	/// Load every `*.toml` file in `dir` as a ToolDef. Files that fail to parse
75	/// are reported on stderr and skipped — one bad tool shouldn't disable all
76	/// the others. Returns an empty vec if the directory doesn't exist.
77	pub fn load_from_dir(dir: &Path) -> Vec<ToolDef> {
78	    let entries = match std::fs::read_dir(dir) {
79	        Ok(e) => e,
80	        Err(_) => return Vec::new(),
81	    };
82	    let mut out = Vec::new();
83	    for entry in entries.flatten() {
84	        let path = entry.path();
85	        if path.extension().and_then(|s| s.to_str()) != Some("toml") {
86	            continue;
87	        }
88	        match parse_file(&path) {
89	            Ok(def) => out.push(def),
90	            Err(e) => eprintln!("Tool load warning: {}: {e}", path.display()),
91	        }
92	    }
93	    out.sort_by(|a, b| a.name.cmp(&b.name));
94	    out
95	}
96	
97	fn parse_file(path: &Path) -> Result<ToolDef, String> {
98	    let body = std::fs::read_to_string(path).map_err(|e| e.to_string())?;
99	    toml::from_str::<ToolDef>(&body).map_err(|e| e.to_string())
100	}
101	
102	/// On first launch (or whenever the user's tools dir is empty), seed the
103	/// directory with the 5 default tool TOMLs that ship in the binary. Users
104	/// can edit, delete, or replace them — we don't overwrite on subsequent
105	/// launches.
106	pub fn seed_defaults_if_empty(dir: &Path) {
107	    if dir.exists()
108	        && std::fs::read_dir(dir)
109	            .map(|mut it| it.next().is_some())
110	            .unwrap_or(false)
111	    {
112	        return;
113	    }
114	    if std::fs::create_dir_all(dir).is_err() {
115	        return;
116	    }
117	    for (name, body) in DEFAULT_TOOLS {
118	        let path = dir.join(name);
119	        let _ = std::fs::write(&path, body);
120	    }
121	}
122	
123	/// Convert a ToolDef into the OpenAI `tools[]` JSON shape:
124	/// `{"type":"function","function":{"name","description","parameters"}}`.
125	/// Done at send time so we don't store the wire shape — `ToolDef` is the
126	/// in-process truth.
127	pub fn to_api_shape(defs: &[ToolDef]) -> Vec<serde_json::Value> {
128	    defs.iter()
129	        .map(|d| {
130	            serde_json::json!({
131	                "type": "function",
132	                "function": {
133	                    "name": d.name,
134	                    "description": d.description,
135	                    "parameters": d.parameters,
136	                },
137	            })
138	        })
139	        .collect()
140	}
141	
142	// ---- builtin handlers ----
143	
144	/// Caps and tunables for builtin tools. Centralized so tests can refer to
145	/// the same constants the production code does.
146	pub mod limits {
147	    pub const READ_FILE_MAX_BYTES: usize = 100 * 1024;
148	    pub const SEARCH_MAX_MATCHES: usize = 200;
149	    pub const SHELL_OUTPUT_MAX_BYTES: usize = 50 * 1024;
150	    /// Per-call wall-clock cap on shell tool execution. Sized for typical
151	    /// dev workflows (`cargo build`, `cargo test`, `npm install`) which
152	    /// routinely exceed a minute. A runaway model can still hit this and
153	    /// stop, but legitimate work isn't cut off prematurely.
154	    pub const SHELL_TIMEOUT_SECS: u64 = 300;
155	}
156	
157	/// Resolve a path argument: absolute paths pass through, relative paths
158	/// join onto `working_dir`. Symlinks are NOT canonicalized — we want the
159	/// user-facing path in error messages, and the tool surface intentionally
160	/// trusts the user to pick what they're willing to expose.
161	fn resolve_path(arg: &str, working_dir: &Path) -> PathBuf {
162	    let p = Path::new(arg);
163	    if p.is_absolute() {
164	        p.to_path_buf()
165	    } else {
166	        working_dir.join(p)
167	    }
168	}
169	
170	fn arg_str<'a>(args: &'a serde_json::Value, key: &str) -> Result<&'a str, String> {
171	    args.get(key)
172	        .and_then(|v| v.as_str())
173	        .ok_or_else(|| format!("missing or non-string argument: {key}"))
174	}
175	
176	/// Run a shell-handler tool: substitute `{{name}}` placeholders in the argv
177	/// template with values from the call's arguments object, then exec it
178	/// with `working_dir` as cwd. Captures stdout + stderr + exit status.
179	pub fn run_shell_tool(
180	    template: &[String],
181	    args: &serde_json::Value,
182	    working_dir: &Path,
183	) -> Result<String, String> {
184	    use std::process::{Command, Stdio};
185	    if template.is_empty() {
186	        return Err("shell tool template is empty".to_string());
187	    }
188	    let resolved: Vec<String> = template
189	        .iter()
190	        .map(|piece| substitute_placeholders(piece, args))
191	        .collect();
192	    let mut cmd = Command::new(&resolved[0]);
193	    cmd.args(&resolved[1..])
194	        .current_dir(working_dir)
195	        .stdout(Stdio::piped())
196	        .stderr(Stdio::piped());
197	    let mut child = cmd.spawn().map_err(|e| format!("spawn failed: {e}"))?;
198	    let deadline =
199	        std::time::Instant::now() + std::time::Duration::from_secs(limits::SHELL_TIMEOUT_SECS);
200	    loop {
201	        match child.try_wait() {
202	            Ok(Some(_)) => break,
203	            Ok(None) => {
204	                if std::time::Instant::now() >= deadline {
205	                    let _ = child.kill();
206	                    return Err(format!("timed out after {}s", limits::SHELL_TIMEOUT_SECS));
207	                }
208	                std::thread::sleep(std::time::Duration::from_millis(50));
209	            }
210	            Err(e) => return Err(format!("wait failed: {e}")),
211	        }
212	    }
213	    let out = child
214	        .wait_with_output()
215	        .map_err(|e| format!("collect failed: {e}"))?;
216	    let mut combined = String::new();
217	    if !out.stdout.is_empty() {
218	        combined.push_str("--- stdout ---\n");
219	        combined.push_str(&String::from_utf8_lossy(&out.stdout));
220	        if !combined.ends_with('\n') {
221	            combined.push('\n');
222	        }
223	    }
224	    if !out.stderr.is_empty() {
225	        combined.push_str("--- stderr ---\n");
226	        combined.push_str(&String::from_utf8_lossy(&out.stderr));
227	        if !combined.ends_with('\n') {
228	            combined.push('\n');
229	        }
230	    }
231	    combined.push_str(&format!(
232	        "--- exit: {} ---",
233	        out.status.code().unwrap_or(-1)
234	    ));
235	    Ok(truncate_with_marker(&combined, limits::SHELL_OUTPUT_MAX_BYTES))
236	}
