238	/// Replace `{{name}}` occurrences in `s` with the string value of the
239	/// matching key in `args` (an object). Missing keys substitute as empty
240	/// string. Non-string values are stringified via `Display` for primitives,
241	/// `to_string()` for objects/arrays.
242	fn substitute_placeholders(s: &str, args: &serde_json::Value) -> String {
243	    let mut out = String::with_capacity(s.len());
244	    let bytes = s.as_bytes();
245	    let mut i = 0;
246	    while i < bytes.len() {
247	        if i + 1 < bytes.len() && bytes[i] == b'{' && bytes[i + 1] == b'{' {
248	            // Find matching '}}' — scan ahead.
249	            if let Some(end) = find_close(s, i + 2) {
250	                let key = &s[i + 2..end];
251	                let trimmed = key.trim();
252	                let value = match args.get(trimmed) {
253	                    Some(serde_json::Value::String(v)) => v.clone(),
254	                    Some(serde_json::Value::Null) | None => String::new(),
255	                    Some(other) => other.to_string(),
256	                };
257	                out.push_str(&value);
258	                i = end + 2;
259	                continue;
260	            }
261	        }
262	        out.push(bytes[i] as char);
263	        i += 1;
264	    }
265	    out
266	}
267	
268	fn find_close(s: &str, from: usize) -> Option<usize> {
269	    let bytes = s.as_bytes();
270	    let mut i = from;
271	    while i + 1 < bytes.len() {
272	        if bytes[i] == b'}' && bytes[i + 1] == b'}' {
273	            return Some(i);
274	        }
275	        i += 1;
276	    }
277	    None
278	}
