280	/// Dispatch a builtin tool by name. Unknown names return an error rather
281	/// than panicking — a stale TOML referring to a removed builtin shouldn't
282	/// crash the app.
283	pub fn run_builtin(
284	    name: &str,
285	    args: &serde_json::Value,
286	    working_dir: &Path,
287	) -> Result<String, String> {
288	    match name {
289	        "read_file" => builtin_read_file(args, working_dir),
290	        "list_directory" => builtin_list_directory(args, working_dir),
291	        "search_files" => builtin_search_files(args, working_dir),
292	        "write_file" => builtin_write_file(args, working_dir),
293	        "run_shell" => builtin_run_shell(args, working_dir),
294	        other => Err(format!("unknown builtin tool: {other}")),
295	    }
296	}
