298	fn builtin_read_file(args: &serde_json::Value, wd: &Path) -> Result<String, String> {
299	    let path = resolve_path(arg_str(args, "path")?, wd);
300	    let offset = args.get("offset").and_then(|v| v.as_u64()).unwrap_or(0);
301	    let limit = args.get("limit").and_then(|v| v.as_u64());
302	    let body = std::fs::read_to_string(&path)
303	        .map_err(|e| format!("read failed: {}: {e}", path.display()))?;
304	
305	    if offset == 0 && limit.is_none() {
306	        return Ok(truncate_with_marker(&body, limits::READ_FILE_MAX_BYTES));
307	    }
308	
309	    // Line slicing path. `offset` is 1-indexed per the TOML doc.
310	    let start = offset.saturating_sub(1) as usize;
311	    let take = limit.map(|n| n as usize).unwrap_or(usize::MAX);
312	    let mut out = String::new();
313	    for line in body.lines().skip(start).take(take) {
314	        out.push_str(line);
315	        out.push('\n');
316	        if out.len() >= limits::READ_FILE_MAX_BYTES {
317	            break;
318	        }
319	    }
320	    Ok(truncate_with_marker(&out, limits::READ_FILE_MAX_BYTES))
321	}
322	
323	fn builtin_list_directory(args: &serde_json::Value, wd: &Path) -> Result<String, String> {
324	    let path = resolve_path(arg_str(args, "path")?, wd);
325	    let entries = std::fs::read_dir(&path)
326	        .map_err(|e| format!("list failed: {}: {e}", path.display()))?;
327	    let mut rows: Vec<(bool, String)> = Vec::new();
328	    for entry in entries.flatten() {
329	        let name = entry.file_name().to_string_lossy().into_owned();
330	        let is_dir = entry.file_type().map(|t| t.is_dir()).unwrap_or(false);
331	        rows.push((is_dir, name));
332	    }
333	    // Directories first, then files; both alphabetical.
334	    rows.sort_by(|a, b| b.0.cmp(&a.0).then_with(|| a.1.cmp(&b.1)));
335	    let mut out = String::new();
336	    for (is_dir, name) in rows {
337	        out.push_str(if is_dir { "d/ " } else { "f/ " });
338	        out.push_str(&name);
339	        out.push('\n');
340	    }
341	    if out.is_empty() {
342	        out.push_str("(empty directory)\n");
343	    }
344	    Ok(out)
345	}
