347	fn builtin_search_files(args: &serde_json::Value, wd: &Path) -> Result<String, String> {
348	    let pattern = arg_str(args, "pattern")?;
349	    let root = resolve_path(arg_str(args, "path")?, wd);
350	    let re = regex::Regex::new(pattern).map_err(|e| format!("invalid regex: {e}"))?;
351	    let mut matches: Vec<String> = Vec::new();
352	    walk_search(&root, &re, &mut matches);
353	    if matches.is_empty() {
354	        return Ok("(no matches)".to_string());
355	    }
356	    Ok(matches.join("\n"))
357	}
