359	/// Recursively walk `dir`, reading text files and emitting `path:lineno: line`
360	/// for each regex match. Skips hidden directories (`.git`, `.cache`, etc.)
361	/// and binary files (heuristic: contains a NUL byte in the first 1KB).
362	/// Stops early once `SEARCH_MAX_MATCHES` is reached.
363	fn walk_search(dir: &Path, re: &regex::Regex, out: &mut Vec<String>) {
364	    if out.len() >= limits::SEARCH_MAX_MATCHES {
365	        return;
366	    }
367	    let entries = match std::fs::read_dir(dir) {
368	        Ok(e) => e,
369	        Err(_) => return,
370	    };
371	    for entry in entries.flatten() {
372	        if out.len() >= limits::SEARCH_MAX_MATCHES {
373	            return;
374	        }
375	        let path = entry.path();
376	        let name = entry.file_name().to_string_lossy().into_owned();
377	        if name.starts_with('.') {
378	            continue;
379	        }
380	        let ft = match entry.file_type() {
381	            Ok(t) => t,
382	            Err(_) => continue,
383	        };
384	        if ft.is_dir() {
385	            walk_search(&path, re, out);
386	        } else if ft.is_file() {
387	            search_one_file(&path, re, out);
388	        }
389	    }
390	}
391	
392	fn search_one_file(path: &Path, re: &regex::Regex, out: &mut Vec<String>) {
393	    let body = match std::fs::read(path) {
394	        Ok(b) => b,
395	        Err(_) => return,
396	    };
397	    // Binary heuristic: a NUL byte in the head means we treat as binary.
398	    if body.iter().take(1024).any(|&b| b == 0) {
399	        return;
400	    }
401	    let text = match std::str::from_utf8(&body) {
402	        Ok(s) => s,
403	        Err(_) => return,
404	    };
405	    for (lineno, line) in text.lines().enumerate() {
406	        if out.len() >= limits::SEARCH_MAX_MATCHES {
407	            return;
408	        }
409	        if re.is_match(line) {
410	            out.push(format!("{}:{}: {}", path.display(), lineno + 1, line));
411	        }
412	    }
413	}
