415	fn builtin_write_file(args: &serde_json::Value, wd: &Path) -> Result<String, String> {
416	    let path = resolve_path(arg_str(args, "path")?, wd);
417	    let content = arg_str(args, "content")?;
418	    let append = args.get("append").and_then(|v| v.as_bool()).unwrap_or(false);
419	    if let Some(parent) = path.parent() {
420	        std::fs::create_dir_all(parent)
421	            .map_err(|e| format!("mkdir failed: {}: {e}", parent.display()))?;
422	    }
423	    if append {
424	        use std::io::Write;
425	        let mut f = std::fs::OpenOptions::new()
426	            .create(true)
427	            .append(true)
428	            .open(&path)
429	            .map_err(|e| format!("open failed: {}: {e}", path.display()))?;
430	        f.write_all(content.as_bytes())
431	            .map_err(|e| format!("write failed: {}: {e}", path.display()))?;
432	    } else {
433	        std::fs::write(&path, content)
434	            .map_err(|e| format!("write failed: {}: {e}", path.display()))?;
435	    }
436	    Ok(format!(
437	        "wrote {} bytes to {}",
438	        content.len(),
439	        path.display()
440	    ))
441	}
