443	fn builtin_run_shell(args: &serde_json::Value, wd: &Path) -> Result<String, String> {
444	    let command = arg_str(args, "command")?;
445	    use std::process::{Command, Stdio};
446	    let mut child = Command::new("sh")
447	        .arg("-c")
448	        .arg(command)
449	        .current_dir(wd)
450	        .stdout(Stdio::piped())
451	        .stderr(Stdio::piped())
452	        .spawn()
453	        .map_err(|e| format!("spawn failed: {e}"))?;
454	
455	    // Wait with a timeout so a runaway command can't hang the app forever.
456	    let deadline =
457	        std::time::Instant::now() + std::time::Duration::from_secs(limits::SHELL_TIMEOUT_SECS);
458	    loop {
459	        match child.try_wait() {
460	            Ok(Some(_)) => break,
461	            Ok(None) => {
462	                if std::time::Instant::now() >= deadline {
463	                    let _ = child.kill();
464	                    return Err(format!(
465	                        "timed out after {}s",
466	                        limits::SHELL_TIMEOUT_SECS
467	                    ));
468	                }
469	                std::thread::sleep(std::time::Duration::from_millis(50));
470	            }
471	            Err(e) => return Err(format!("wait failed: {e}")),
472	        }
473	    }
474	    let output = child
475	        .wait_with_output()
476	        .map_err(|e| format!("collect failed: {e}"))?;
477	    let stdout = String::from_utf8_lossy(&output.stdout);
478	    let stderr = String::from_utf8_lossy(&output.stderr);
479	    let exit = output.status.code().unwrap_or(-1);
480	    let mut combined = String::new();
481	    if !stdout.is_empty() {
482	        combined.push_str("--- stdout ---\n");
483	        combined.push_str(&stdout);
484	        if !combined.ends_with('\n') {
485	            combined.push('\n');
486	        }
487	    }
488	    if !stderr.is_empty() {
489	        combined.push_str("--- stderr ---\n");
490	        combined.push_str(&stderr);
491	        if !combined.ends_with('\n') {
492	            combined.push('\n');
493	        }
494	    }
495	    combined.push_str(&format!("--- exit: {exit} ---"));
496	    Ok(truncate_with_marker(&combined, limits::SHELL_OUTPUT_MAX_BYTES))
497	}
