499	/// Truncate a string to `max_bytes` and append a marker so the model knows
500	/// the result was clipped. Char-aware so we don't slice through a multi-
501	/// byte UTF-8 boundary.
502	fn truncate_with_marker(s: &str, max_bytes: usize) -> String {
503	    if s.len() <= max_bytes {
504	        return s.to_string();
505	    }
506	    let mut end = max_bytes;
507	    while end > 0 && !s.is_char_boundary(end) {
508	        end -= 1;
509	    }
510	    format!("{}\n... [truncated, {} more bytes]", &s[..end], s.len() - end)
511	}
