765	    #[test]
766	    fn unknown_builtin_returns_error_not_panic() {
767	        assert!(run_builtin("nonexistent", &serde_json::json!({}), &std::env::temp_dir()).is_err());
768	    }
769	
770	    #[test]
771	    fn substitute_placeholders_string_value() {
772	        let args = serde_json::json!({"name": "alice", "id": 42});
773	        assert_eq!(
774	            substitute_placeholders("hello {{name}} #{{id}}", &args),
775	            "hello alice #42"
776	        );
