184	pub async fn fetch_models(base_url: &str, api_key: Option<&str>) -> Result<Vec<ModelInfo>, String> {
185	    let client = Client::builder()
186	        .timeout(REQUEST_TIMEOUT)
187	        .connect_timeout(CONNECT_TIMEOUT)
188	        .build()
189	        .map_err(|e| format!("Failed to create HTTP client: {e}"))?;
190	
191	    let mut url = base_url.trim_end_matches('/').to_string();
192	
193	    // Auto-fix OpenRouter URLs (users often provide just the domain or the
194	    // completions endpoint). Only rewrite when the URL's host is literally
195	    // openrouter.ai — substring matching would let `evil.com/openrouter.ai`
196	    // hijack the rewrite and leak the bearer token.
197	    let is_openrouter = host_is(&url, "openrouter.ai");
198	    if is_openrouter {
199	        url = "https://openrouter.ai/api/v1".to_string();
200	    } else if url.ends_with("/chat/completions") {
201	        url = url.trim_end_matches("/chat/completions").to_string();
202	    }
203	
204	    // Try OpenAI-standard /v1/models first (works for OpenRouter, LM Studio, vLLM, etc.)
205	    let models_url = if url.ends_with("/v1") {
206	        format!("{url}/models")
207	    } else {
208	        format!("{url}/v1/models")
209	    };
210	
211	    let mut request = client.get(&models_url);
212	    if let Some(key) = api_key {
213	        request = request.bearer_auth(key);
214	    }
215	    if is_openrouter {
216	        request = request
217	            .header("HTTP-Referer", "https://github.com/heath0xFF/fornax")
218	            .header("X-Title", "Fornax");
219	    }
220	
221	    // Track "200 with empty data" separately from "didn't respond at all" so
222	    // we can tell LM-Studio-with-no-model-loaded (helpful hint) apart from
223	    // server-not-running (raw connection error).
224	    let mut openai_responded_empty = false;
225	    if let Ok(resp) = request.send().await {
226	        if resp.status().is_success() {
227	            if let Ok(openai_resp) = resp.json::<OpenAIModelsResponse>().await {
228	                let models: Vec<ModelInfo> = openai_resp
229	                    .data
230	                    .into_iter()
231	                    .map(|m| ModelInfo {
232	                        context_window: m.max_model_len.or(m.context_length),
233	                        id: m.id,
234	                    })
235	                    .collect();
236	                if !models.is_empty() {
237	                    return Ok(models);
238	                }
239	                openai_responded_empty = true;
240	            }
241	        }
242	    }
243	
244	    // Fall back to Ollama /api/tags
245	    let api_base = url.trim_end_matches("/v1");
246	    let tags_result: Result<Vec<ModelInfo>, String> =
247	        match client.get(format!("{api_base}/api/tags")).send().await {
248	            Ok(r) if r.status().is_success() => r
249	                .json::<OllamaTagsResponse>()
250	                .await
251	                .map(|t| {
252	                    t.models
253	                        .into_iter()
254	                        .map(|m| ModelInfo { id: m.name, context_window: None })
255	                        .collect()
256	                })
257	                .map_err(|e| format!("Failed to parse models: {e}")),
258	            Ok(r) => Err(format!("Models endpoint returned {}", r.status())),
259	            Err(e) => Err(format!("Failed to fetch models: {e}")),
260	        };
261	
262	    match tags_result {
263	        Ok(m) if !m.is_empty() => Ok(m),
264	        // Ollama path returned an empty list (server reachable, nothing
265	        // pulled) — surface the actionable hint, not a silent empty dropdown.
266	        Ok(_) => Err(NO_MODELS_HINT.to_string()),
267	        // Ollama path errored but OpenAI returned 200 with empty data — this
268	        // is the LM-Studio-no-model-loaded case. Use the hint instead of the
269	        // raw Ollama parse/404 error, which would be misleading.
270	        Err(_) if openai_responded_empty => Err(NO_MODELS_HINT.to_string()),
271	        Err(e) => Err(e),
272	    }
273	}
