275	pub struct ChatParams {
276	    pub base_url: String,
277	    pub model: String,
278	    pub messages: Vec<Message>,
279	    pub temperature: Option<f32>,
280	    pub max_tokens: Option<u32>,
281	    pub top_p: Option<f32>,
282	    pub frequency_penalty: Option<f32>,
283	    pub presence_penalty: Option<f32>,
284	    pub stop_sequences: Option<Vec<String>>,
285	    pub api_key: Option<String>,
286	    /// OpenAI tools array. None = no tool calling for this turn.
287	    pub tools: Option<Vec<serde_json::Value>>,
288	}
289	
290	pub fn stream_chat(
291	    params: ChatParams,
292	    tx: mpsc::UnboundedSender<StreamEvent>,
293	    cancel: CancellationToken,
294	) {
295	    tokio::spawn(async move {
296	        let ChatParams {
297	            base_url,
298	            model,
299	            messages,
300	            temperature,
301	            max_tokens,
302	            top_p,
303	            frequency_penalty,
304	            presence_penalty,
305	            stop_sequences,
306	            api_key,
307	            tools,
308	        } = params;
309	        let client = match Client::builder().connect_timeout(CONNECT_TIMEOUT).build() {
310	            Ok(c) => c,
311	            Err(e) => {
312	                let _ = tx.send(StreamEvent::Error(format!(
313	                    "Failed to create HTTP client: {e}"
314	                )));
315	                return;
316	            }
317	        };
318	        let mut base_url = base_url.trim_end_matches('/').to_string();
319	
320	        let is_openrouter = host_is(&base_url, "openrouter.ai");
321	        if is_openrouter {
322	            base_url = "https://openrouter.ai/api/v1".to_string();
323	        } else if base_url.ends_with("/chat/completions") {
324	            base_url = base_url.trim_end_matches("/chat/completions").to_string();
325	        }
326	
327	        let url = format!("{}/chat/completions", base_url);
328	
329	        let req = ChatRequest {
330	            model,
331	            messages,
332	            stream: true,
333	            temperature,
334	            max_tokens,
335	            top_p,
336	            frequency_penalty,
337	            presence_penalty,
338	            stop_sequences,
339	            tools,
340	            stream_options: Some(StreamOptions {
341	                include_usage: true,
342	            }),
343	        };
344	
345	        let mut request = client.post(&url).json(&req);
346	        if let Some(key) = &api_key {
347	            request = request.bearer_auth(key);
348	        }
349	        if is_openrouter {
350	            request = request
351	                .header("HTTP-Referer", "https://github.com/heath0xFF/fornax")
352	                .header("X-Title", "Fornax");
353	        }
354	
355	        let resp = match request.send().await {
356	            Ok(r) => r,
357	            Err(e) => {
358	                let _ = tx.send(StreamEvent::Error(format!("Request failed: {e}")));
359	                return;
360	            }
361	        };
362	
363	        if !resp.status().is_success() {
364	            let status = resp.status();
365	            let body = resp
366	                .bytes()
367	                .await
368	                .map(|b| {
369	                    let truncated = &b[..b.len().min(MAX_ERROR_BODY)];
370	                    String::from_utf8_lossy(truncated).into_owned()
371	                })
372	                .unwrap_or_default();
373	            // Log full error for debugging but only show sanitized message in UI
374	            eprintln!("API error {status}: {body}");
375	            let message = match status.as_u16() {
376	                401 => format!("{status}: Authentication failed — check your API key"),
377	                403 => format!("{status}: Access denied"),
378	                404 => format!("{status}: Endpoint not found — check your URL"),
379	                429 => format!("{status}: Rate limited — try again later"),
380	                500..=599 => format!("{status}: Server error"),
381	                _ => format!("{status}: Request failed"),
382	            };
383	            let _ = tx.send(StreamEvent::Error(message));
384	            return;
385	        }
386	
387	        let mut stream = resp.bytes_stream();
388	        // Use a byte buffer to handle UTF-8 sequences split across chunks
389	        let mut raw_buf: Vec<u8> = Vec::new();
390	
391	        // Tool call accumulator: index → (id, name, arguments-so-far). We
392	        // assemble per-slot across deltas and emit a single ToolCalls event
393	        // before Done. Using a Vec<Option<_>> keyed by index handles sparse
394	        // / out-of-order deltas without allocating a HashMap for what's
395	        // typically 1–3 calls.
396	        let mut tool_acc: Vec<Option<(Option<String>, String, String)>> = Vec::new();
397	
398	        loop {
399	            tokio::select! {
400	                _ = cancel.cancelled() => {
401	                    flush_tool_calls(&mut tool_acc, &tx);
402	                    let _ = tx.send(StreamEvent::Done);
403	                    return;
404	                }
405	                chunk = stream.next() => {
406	                    let Some(chunk) = chunk else {
407	                        flush_tool_calls(&mut tool_acc, &tx);
408	                        let _ = tx.send(StreamEvent::Done);
409	                        return;
410	                    };
411	
412	                    let bytes = match chunk {
413	                        Ok(b) => b,
414	                        Err(e) => {
415	                            let _ = tx.send(StreamEvent::Error(format!("Stream error: {e}")));
416	                            return;
417	                        }
418	                    };
419	
420	                    if raw_buf.len() + bytes.len() > MAX_STREAM_BUFFER {
421	                        let _ = tx.send(StreamEvent::Error("Stream buffer overflow".to_string()));
422	                        return;
423	                    }
424	
425	                    raw_buf.extend_from_slice(&bytes);
426	
427	                    // Find the last valid UTF-8 boundary to avoid splitting multi-byte chars
428	                    let valid_up_to = match std::str::from_utf8(&raw_buf) {
429	                        Ok(_) => raw_buf.len(),
430	                        Err(e) => e.valid_up_to(),
431	                    };
432	
433	                    if valid_up_to == 0 {
434	                        continue;
435	                    }
436	
437	                    // Safe: we just validated this range is valid UTF-8
438	                    let text = std::str::from_utf8(&raw_buf[..valid_up_to]).unwrap();
439	                    let mut remaining_start = 0;
440	
441	                    for line_end in newline_positions(text) {
442	                        let line = text[remaining_start..line_end].trim();
443	                        remaining_start = line_end + 1;
444	
445	                        if line.is_empty() || line.starts_with(':') {
446	                            continue;
447	                        }
448	
449	                        let data = if let Some(d) = line.strip_prefix("data: ") {
450	                            d.trim()
451	                        } else {
452	                            continue;
453	                        };
454	
455	                        if data == "[DONE]" {
456	                            flush_tool_calls(&mut tool_acc, &tx);
457	                            let _ = tx.send(StreamEvent::Done);
458	                            return;
459	                        }
460	
461	                        if let Ok(chunk) = serde_json::from_str::<ChatChunk>(data) {
462	                            if let Some(choices) = chunk.choices {
463	                                for choice in choices {
464	                                    if let Some(delta) = choice.delta {
465	                                        // Skip empty strings: some providers
466	                                        // (Ollama qwen3 thinking, OpenAI keep-
467	                                        // alives) emit `content: ""` alongside
468	                                        // a reasoning delta. Treating that as
469	                                        // "content arrived" prematurely closes
470	                                        // the <think> block and the next
471	                                        // reasoning delta re-opens a new one,
472	                                        // producing dozens of tiny blocks.
473	                                        if let Some(reasoning) = delta.reasoning
474	                                            && !reasoning.is_empty()
475	                                        {
476	                                            let _ = tx.send(StreamEvent::Reasoning(reasoning));
477	                                        }
478	                                        if let Some(content) = delta.content
479	                                            && !content.is_empty()
480	                                        {
481	                                            let _ = tx.send(StreamEvent::Token(content));
482	                                        }
483	                                        if let Some(tcds) = delta.tool_calls {
484	                                            for tcd in tcds {
485	                                                accumulate_tool_call(&mut tool_acc, tcd);
486	                                            }
487	                                        }
488	                                    }
489	                                }
490	                            }
491	                            if let Some(usage) = chunk.usage {
492	                                let _ = tx.send(StreamEvent::UsageInfo(usage));
493	                            }
494	                        }
495	                    }
496	
497	                    // Keep unprocessed bytes (incomplete line + any trailing invalid UTF-8)
498	                    let consumed = remaining_start.min(valid_up_to);
499	                    raw_buf = raw_buf[consumed..].to_vec();
500	                }
501	            }
502	        }
503	    });
504	}
505	
506	/// Append a streaming `ToolCallDelta` into the accumulator. The accumulator
507	/// is keyed by the slot `index` so out-of-order deltas across chunks land
508	/// in the right slot. `id` and `name` arrive once each (usually in the
509	/// first delta for a slot); `arguments` is concatenated piecewise.
510	fn accumulate_tool_call(
511	    acc: &mut Vec<Option<(Option<String>, String, String)>>,
512	    d: ToolCallDelta,
513	) {
514	    while acc.len() <= d.index {
515	        acc.push(None);
516	    }
517	    let slot = acc[d.index].get_or_insert_with(|| (None, String::new(), String::new()));
518	    if let Some(id) = d.id {
519	        slot.0 = Some(id);
520	    }
521	    if let Some(f) = d.function {
522	        if let Some(name) = f.name {
523	            slot.1 = name;
524	        }
525	        if let Some(args) = f.arguments {
526	            slot.2.push_str(&args);
527	        }
528	    }
529	}
530	
531	/// Drain the accumulator into a final `ToolCalls` event. Slots missing an
532	/// id are dropped (and logged) — without an id we can't match a result
533	/// back. No-op if no calls were accumulated, so emitting unconditionally
534	/// before Done is safe.
535	fn flush_tool_calls(
536	    acc: &mut Vec<Option<(Option<String>, String, String)>>,
537	    tx: &mpsc::UnboundedSender<StreamEvent>,
538	) {
539	    let calls: Vec<ToolCall> = acc
540	        .drain(..)
541	        .enumerate()
542	        .filter_map(|(slot_idx, slot)| {
543	            let (id, name, args) = slot?;
544	            let Some(id) = id else {
545	                // The model thinks it called this tool; we'd be telling it
546	                // nothing came back. Surface a diagnostic so the dropped
547	                // call is at least debuggable.
548	                eprintln!(
549	                    "tool_call slot {slot_idx} ('{name}') arrived without an id — dropping"
550	                );
551	                return None;
552	            };
553	            Some(ToolCall {
554	                id,
555	                call_type: "function".to_string(),
556	                function: ToolCallFunction {
557	                    name,
558	                    arguments: args,
559	                },
560	            })
561	        })
562	        .collect();
563	    if !calls.is_empty() {
564	        let _ = tx.send(StreamEvent::ToolCalls(calls));
565	    }
566	}
567	
568	/// Find all newline positions in a string slice
569	fn newline_positions(s: &str) -> impl Iterator<Item = usize> + '_ {
570	    s.bytes()
571	        .enumerate()
572	        .filter_map(|(i, b)| if b == b'\n' { Some(i) } else { None })
573	}
