601	/// Single-shot non-streaming chat completion. Used by auto-title (one short
602	/// reply, no streaming UI). Always returns the full assistant message string
603	/// or an error.
604	pub async fn complete_once(
605	    base_url: &str,
606	    model: &str,
607	    messages: &[Message],
608	    api_key: Option<&str>,
609	    max_tokens: Option<u32>,
610	    temperature: Option<f32>,
611	) -> Result<String, String> {
612	    let client = Client::builder()
613	        .timeout(REQUEST_TIMEOUT)
614	        .connect_timeout(CONNECT_TIMEOUT)
615	        .build()
616	        .map_err(|e| format!("Failed to create HTTP client: {e}"))?;
617	
618	    let mut base_url = base_url.trim_end_matches('/').to_string();
619	    let is_openrouter = host_is(&base_url, "openrouter.ai");
620	    if is_openrouter {
621	        base_url = "https://openrouter.ai/api/v1".to_string();
622	    } else if base_url.ends_with("/chat/completions") {
623	        base_url = base_url.trim_end_matches("/chat/completions").to_string();
624	    }
625	    let url = format!("{}/chat/completions", base_url);
626	
627	    let req = NonStreamingChatRequest {
628	        model,
629	        messages,
630	        stream: false,
631	        max_tokens,
632	        temperature,
633	    };
634	
635	    let mut request = client.post(&url).json(&req);
636	    if let Some(key) = api_key {
637	        request = request.bearer_auth(key);
638	    }
639	    if is_openrouter {
640	        request = request
641	            .header("HTTP-Referer", "https://github.com/heath0xFF/fornax")
642	            .header("X-Title", "Fornax");
643	    }
644	
645	    let resp = request
646	        .send()
647	        .await
648	        .map_err(|e| format!("Request failed: {e}"))?;
649	    if !resp.status().is_success() {
650	        let status = resp.status();
651	        return Err(format!("{status}"));
652	    }
653	    let parsed: NonStreamingChatResponse = resp
654	        .json()
655	        .await
656	        .map_err(|e| format!("Failed to parse response: {e}"))?;
657	    parsed
658	        .choices
659	        .into_iter()
660	        .next()
661	        .and_then(|c| c.message.content)
662	        .ok_or_else(|| "Empty response".to_string())
663	}
