  title: string;
  pinned: boolean;
  project_id: number | null;
  runtime: string | null;
}

export interface ProjectDto {
  id: number;
  name: string;
  pinned: boolean;
}

export interface UsageByModel {
  model: string;
  endpoint: string;
  requests: number;
  prompt_tokens: number;
  completion_tokens: number;
  total_tokens: number;
  cost: number;
  avg_ttft_ms: number | null;
  avg_decode_tok_s: number | null;
}

export interface UsageDaily {
  date: string;
  total_tokens: number;
}

export interface BenchParams {
  endpoint: string;
  model: string;
  prompt: string;
  max_tokens: number;
  concurrency: number;
  total_requests: number;
}

export interface BenchAgg {
  avg: number | null;
  p50: number | null;
  p95: number | null;
}

export interface BenchResult {
  requests: number;
  ok: number;
  errors: number;
  wall_ms: number;
  ttft_ms: BenchAgg;
  decode_tok_s: BenchAgg;
  agg_decode_tok_s: number;
  total_completion_tokens: number;
  ttft_series: number[];
  decode_series: number[];
}

export interface UsageStats {
  total_requests: number;
  ok_requests: number;
  prompt_tokens: number;
  completion_tokens: number;
  total_tokens: number;
  total_cost: number;
  ttft_p50_ms: number | null;
  ttft_p95_ms: number | null;
  decode_p50_tok_s: number | null;
  decode_p95_tok_s: number | null;
  by_model: UsageByModel[];
  daily: UsageDaily[];
}

export interface ToolCallDto {
  id: string;
  name: string;
  arguments: string;
}

export interface MessageDto {
  id: number | null;
  role: "system" | "user" | "assistant" | "tool";
  text: string;
  images: string[];
  tool_calls: ToolCallDto[] | null;
  tool_call_id: string | null;
  created_at: number | null;
}

export interface SettingsDto {
  model: string | null;
  endpoint: string;
  system_prompt: string;
  temperature: number;
  max_tokens: number;
  use_max_tokens: boolean;
  top_p: number | null;
  frequency_penalty: number | null;
  presence_penalty: number | null;
  stop_sequences: string[];
  working_dir: string | null;
  /** Effective auto-compaction settings (per-conversation over global). */
  auto_compact: boolean;
  compact_threshold_pct: number;
  compact_keep_recent: number;
}

export interface ConversationData {
  messages: MessageDto[];
  settings: SettingsDto;
  draft: string | null;
  /** Persisted compaction summary + the message id it covers up to (inclusive). */
  summary: string | null;
  summary_through: number | null;
}

// Shared generation knobs (flattened into the request payloads server-side).
export interface GenParams {
  endpoint: string;
  model: string;
  system_prompt: string;
  temperature: number | null;
  max_tokens: number | null;
  use_max_tokens: boolean;
  top_p: number | null;
  frequency_penalty: number | null;
  presence_penalty: number | null;
  stop_sequences: string[];
  /** Effective auto-compaction settings, merged on the frontend. */
  auto_compact: boolean;
  compact_threshold_pct: number;
  compact_keep_recent: number;
}

export interface SendParams extends GenParams {
  conversation_id: number | null;
  user_text: string;
  images: string[];
}

export interface SiblingInfo {
  index: number;
  total: number;
  ids: number[];
}

export interface GpuDevice {
  name: string;
  util_pct: number;
  mem_used_gb: number;
  mem_total_gb: number;
  temp_c: number;
  power_w: number;
  power_limit_w: number;
}

export interface GpuStats {
  source: string;
  vram_used_gb: number | null;
  vram_total_gb: number | null;
  power_w: number | null;
  power_limit_w: number | null;
  temp_c: number | null;
  util_pct: number | null;
  devices: GpuDevice[];
}

export interface ServerStats {
  decode_tok_s: number | null;
  prefill_tok_s: number | null;
  ttft_ms: number | null;
  requests_running: number | null;
  requests_waiting: number | null;
  kv_cache_pct: number | null;
  prompt_tokens_total: number | null;
  generation_tokens_total: number | null;
}

export interface MetricsSnapshot {
  endpoint: string;
  runtime: string;
  gpu: GpuStats | null;
  server: ServerStats | null;
}

export interface AgentCommand {
  name: string;
  description: string;
  body: string;
}

export interface Skill {
  name: string;
  description: string;
  body: string;
}

export interface AgentsDto {
  commands: AgentCommand[];
  skills: Skill[];
}

export interface PresetDto {
  id: number;
  name: string;
  endpoint: string | null;
  model: string | null;
  system_prompt: string | null;
  temperature: number | null;
  max_tokens: number | null;
  use_max_tokens: boolean;
  top_p: number | null;
  frequency_penalty: number | null;
  presence_penalty: number | null;
  stop_sequences: string[];
}

// Streaming events (serde tag = "type", snake_case)
export type ChatEvent =
  | { type: "started"; conversation_id: number }
  | { type: "turn_start" }
  | { type: "token"; text: string }
  | { type: "reasoning"; text: string }
  | { type: "tool_call"; id: string; name: string; arguments: string }
  | { type: "tool_approval"; id: string; name: string; arguments: string }
  | {
      type: "tool_result";
      id: string;
      name: string;
      result: string;
      is_error: boolean;
    }
  | {
      type: "usage";
      prompt_tokens: number | null;
      completion_tokens: number | null;
      total_tokens: number | null;
      cost: number | null;
    }
  | {
      type: "request_metrics";
      ttft_ms: number | null;
      decode_tok_s: number | null;
      prefill_tok_s: number | null;
      duration_ms: number;
    }
  | { type: "done"; message_id: number | null }
  | { type: "error"; message: string }
  | {
      type: "compacted";
      through_id: number;
      summary: string;
      removed: number;
    };

export interface PendingApproval {
  id: string;
  name: string;
  arguments: string;
}

#[derive(Debug, Serialize)]
pub struct ModelInfo {
    pub id: String,
    pub context_window: Option<u32>,
}

#[derive(Serialize)]
struct ChatRequest {
    model: String,
    messages: Vec<Message>,
    stream: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    temperature: Option<f32>,
    #[serde(skip_serializing_if = "Option::is_none")]
    max_tokens: Option<u32>,
    #[serde(skip_serializing_if = "Option::is_none")]
    top_p: Option<f32>,
    #[serde(skip_serializing_if = "Option::is_none")]
    frequency_penalty: Option<f32>,
    #[serde(skip_serializing_if = "Option::is_none")]
    presence_penalty: Option<f32>,
    #[serde(skip_serializing_if = "Option::is_none", rename = "stop")]
    stop_sequences: Option<Vec<String>>,
    /// OpenAI tools array. Each entry is
    /// `{"type":"function","function":{"name","description","parameters"}}`.
    /// Stored as `serde_json::Value` so we don't couple the wire shape into
    /// our type system — `tools.rs` builds these from `ToolDef` at send time.
    #[serde(skip_serializing_if = "Option::is_none")]
    tools: Option<Vec<serde_json::Value>>,
    /// Asks the provider to emit a final `usage` chunk in streaming mode.
    /// OpenAI, LM Studio, and recent vLLM/Ollama gate streaming `usage`
    /// behind this flag; without it the post-response token counter and
    /// cost display stay empty. OpenRouter emits usage either way, so this
    /// is additive across providers.
    #[serde(skip_serializing_if = "Option::is_none")]
    stream_options: Option<StreamOptions>,
}

#[derive(Serialize)]
struct StreamOptions {
    include_usage: bool,
}

#[derive(Deserialize)]
struct ChatChunk {
    choices: Option<Vec<ChunkChoice>>,
    usage: Option<Usage>,
}

#[derive(Deserialize, Clone)]
pub struct Usage {
    pub prompt_tokens: Option<u32>,
    pub completion_tokens: Option<u32>,
    pub total_tokens: Option<u32>,
    /// OpenRouter returns `cost` inside the `usage` object (credits charged)
    pub cost: Option<f64>,
}

#[derive(Deserialize)]
struct ChunkChoice {
    delta: Option<Delta>,
}

#[derive(Deserialize)]
struct Delta {
    content: Option<String>,
    /// Some providers (DeepSeek, OpenRouter forwarding reasoning models) emit a
    /// separate `reasoning` field for chain-of-thought. We surface it as a
    /// `Reasoning` event so the UI can show it collapsed.
    reasoning: Option<String>,
    /// Tool call deltas — OpenAI streams tool_calls piecewise across chunks
    /// indexed by slot. We accumulate them here in api.rs and emit a single
    /// `ToolCalls` event with the assembled list at end-of-stream.
    tool_calls: Option<Vec<ToolCallDelta>>,
}

#[derive(Deserialize)]
struct ToolCallDelta {
    /// Slot index — multiple tool calls in one assistant turn each get a
    /// stable slot, even though their fields trickle in across chunks.
    index: usize,
    id: Option<String>,
    /// Always `"function"` today; we don't surface it because there's only
    /// one variant. Allow-dead so the deserializer accepts the field.
    #[allow(dead_code)]
    #[serde(rename = "type")]
    call_type: Option<String>,
    function: Option<FunctionDelta>,
}

#[derive(Deserialize)]
struct FunctionDelta {
    name: Option<String>,
    /// Arguments stream as string fragments — concatenate to form valid JSON.
    arguments: Option<String>,
}

pub enum StreamEvent {
    Token(String),

